import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns invoices with dueDate before asOf', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);
  // dueDate is 2025-01-29

  const result = overdueInvoices([issued.value], '2025-02-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].number, issued.value.number);
  assert.equal(result.value[0].customerId, 'C-001');
  assert.equal(result.value[0].dueDate, '2025-01-29');
  assert.equal(result.value[0].daysOverdue, 17); // Feb 15 - Jan 29
});

test('overdueInvoices excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);

  const result = overdueInvoices([inv.value], '2025-02-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const payment = recordPayment(issued.value, { amount: 10920, date: '2025-01-20' });
  assert.equal(payment.ok, true);

  const result = overdueInvoices([payment.value], '2025-02-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices excludes invoices with future due dates', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET30',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);
  // dueDate is 2025-02-14

  const result = overdueInvoices([issued.value], '2025-02-10');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices includes invoices with dueDate exactly on asOf (not yet overdue)', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);
  // dueDate is 2025-01-29

  const result = overdueInvoices([issued.value], '2025-01-29');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const payment = recordPayment(issued.value, { amount: 5000, date: '2025-01-20' });
  assert.equal(payment.ok, true);

  const result = overdueInvoices([payment.value], '2025-02-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].number, issued.value.number);
});

test('overdueInvoices calculates due correctly for partially_paid', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const payment = recordPayment(issued.value, { amount: 5000, date: '2025-01-20' });
  assert.equal(payment.ok, true);

  const result = overdueInvoices([payment.value], '2025-02-15');

  assert.equal(result.ok, true);
  // C-001 is gold tier: 9500 - 475 + 1895 = 10920
  // Due is 10920 - 5000 = 5920
  assert.equal(result.value[0].due, 5920);
});

test('overdueInvoices returns DATE_INVALID for bad date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2025-2-15');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('overdueInvoices returns empty array when no overdue invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET30',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2025-02-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices sorts by daysOverdue (most overdue first)', () => {
  // Invoice 1: issued 2025-01-01, dueDate 2025-01-15
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  // Invoice 2: issued 2025-01-10, dueDate 2025-01-24
  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-10',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2025-0001']);
  assert.equal(issued2.ok, true);

  const result = overdueInvoices([issued2.value, issued1.value], '2025-02-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 2);
  // Most overdue should be first (inv1 with 31 days overdue)
  assert.equal(result.value[0].dueDate, '2025-01-15');
  assert.equal(result.value[0].daysOverdue, 31);
  assert.equal(result.value[1].dueDate, '2025-01-24');
  assert.equal(result.value[1].daysOverdue, 22);
});

test('overdueInvoices includes number, customerId, dueDate, daysOverdue, due', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2025-02-15');

  assert.equal(result.ok, true);
  const overdue = result.value[0];
  assert(overdue.number);
  assert.equal(overdue.customerId, 'C-001');
  assert.equal(overdue.dueDate, '2025-01-29');
  assert.equal(typeof overdue.daysOverdue, 'number');
  assert.equal(typeof overdue.due, 'number');
});

test('overdueInvoices with multiple customers', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET7',
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-10',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET7',
  });

  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2025-0001']);
  assert.equal(issued2.ok, true);

  const result = overdueInvoices([issued1.value, issued2.value], '2025-02-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 2);
  assert.equal(result.value[0].customerId, 'C-001');
  assert.equal(result.value[1].customerId, 'C-002');
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);
  // dueDate is 2025-01-29

  const result = overdueInvoices([issued.value], '2025-02-05');

  assert.equal(result.ok, true);
  assert.equal(result.value[0].daysOverdue, 7); // 7 days overdue
});

test('overdueInvoices with many invoices maintains sort order', () => {
  const invoices = [];
  const issuedInvoices = [];

  // Create 5 invoices with different due dates
  for (let i = 0; i < 5; i++) {
    const date = `2025-0${1 + i}-15`;
    const inv = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      terms: 'NET7',
    });

    assert.equal(inv.ok, true);
    const issued = issueInvoice(inv.value, issuedInvoices.length > 0 ? [`INV-2025-${String(i).padStart(4, '0')}`] : []);
    assert.equal(issued.ok, true);
    issuedInvoices.push(issued.value);
  }

  // Shuffle the order before passing
  const shuffled = [issuedInvoices[2], issuedInvoices[0], issuedInvoices[4], issuedInvoices[1], issuedInvoices[3]];

  const result = overdueInvoices(shuffled, '2025-03-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 5);
  // Should be sorted by daysOverdue descending
  for (let i = 0; i < result.value.length - 1; i++) {
    assert(result.value[i].daysOverdue >= result.value[i + 1].daysOverdue);
  }
});

test('overdueInvoices with EOM terms', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);
  // dueDate is 2025-01-31

  const result = overdueInvoices([issued.value], '2025-02-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].dueDate, '2025-01-31');
  assert.equal(result.value[0].daysOverdue, 15); // Feb 15 - Jan 31
});

